const initSqlJs = require('sql.js');
const fs = require('fs');
const path = require('path');

let db = null;

// Initialize the database
async function initDb() {
  try {
    // Initialize sql.js
    const SQL = await initSqlJs();

    // Create database instance (in-memory for now to avoid file issues)
    db = new SQL.Database();

    // Create tables if they don't exist
    createTables();

    console.log('Database initialized successfully');
    return db;
  } catch (error) {
    console.error('Error initializing database:', error);
    throw error;
  }
}

function createTables() {
  // Create users table
  db.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      email TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP
    )
  `);

  // Create tasks table
  db.exec(`
    CREATE TABLE IF NOT EXISTS tasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER REFERENCES users(id),
      title TEXT NOT NULL,
      description TEXT,
      status TEXT DEFAULT 'pending' CHECK(status IN ('pending','in_progress','done')),
      created_at TEXT DEFAULT CURRENT_TIMESTAMP
    )
  `);

  // Create reports table
  db.exec(`
    CREATE TABLE IF NOT EXISTS reports (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER REFERENCES users(id),
      title TEXT NOT NULL,
      content_html TEXT,
      generated_at TEXT DEFAULT CURRENT_TIMESTAMP
    )
  `);

  console.log('Tables created successfully');
}

// Get database instance
function getDb() {
  if (!db) {
    throw new Error('Database not initialized. Call initDb() first.');
  }
  return db;
}

// Helper function to escape SQL strings
function escapeSql(str) {
  if (typeof str !== 'string') return str;
  return str.replace(/'/g, "''");
}

// Helper functions for common operations
function insertUser(email, passwordHash) {
  const result = db.exec(`
    INSERT INTO users (email, password_hash, created_at) 
    VALUES ('${escapeSql(email)}', '${escapeSql(passwordHash)}', datetime('now'))
  `);

  // Get the inserted user
  const users = db.exec(`SELECT * FROM users WHERE email = '${escapeSql(email)}'`);
  return users[0] ? {
    id: users[0].values[0][0],
    email: users[0].values[0][1],
    password_hash: users[0].values[0][2],
    created_at: users[0].values[0][3]
  } : null;
}

function getUserByEmail(email) {
  const result = db.exec(`SELECT * FROM users WHERE email = '${escapeSql(email)}'`);
  if (result.length === 0 || result[0].values.length === 0) return null;

  const row = result[0].values[0];
  return {
    id: row[0],
    email: row[1],
    password_hash: row[2],
    created_at: row[3]
  };
}

function insertTask(userId, title, description, status = 'pending') {
  db.exec(`
    INSERT INTO tasks (user_id, title, description, status, created_at) 
    VALUES (${userId}, '${escapeSql(title)}', '${escapeSql(description || '')}', '${escapeSql(status)}', datetime('now'))
  `);

  // Get the inserted task
  const result = db.exec(`
    SELECT * FROM tasks 
    WHERE user_id = ${userId} AND title = '${escapeSql(title)}' 
    ORDER BY id DESC LIMIT 1
  `);

  if (result.length === 0 || result[0].values.length === 0) return null;

  const row = result[0].values[0];
  return {
    id: row[0],
    user_id: row[1],
    title: row[2],
    description: row[3],
    status: row[4],
    created_at: row[5]
  };
}

function getTasksByUserId(userId) {
  const result = db.exec(`SELECT * FROM tasks WHERE user_id = ${userId} ORDER BY created_at DESC`);
  if (result.length === 0) return [];

  return result[0].values.map(row => ({
    id: row[0],
    user_id: row[1],
    title: row[2],
    description: row[3],
    status: row[4],
    created_at: row[5]
  }));
}

function updateTask(id, title, description, status) {
  const updates = [];
  if (title !== undefined) updates.push(`title = '${escapeSql(title)}'`);
  if (description !== undefined) updates.push(`description = '${escapeSql(description)}'`);
  if (status !== undefined) updates.push(`status = '${escapeSql(status)}'`);

  if (updates.length === 0) return null;

  db.exec(`UPDATE tasks SET ${updates.join(', ')} WHERE id = ${id}`);

  // Get the updated task
  const result = db.exec(`SELECT * FROM tasks WHERE id = ${id}`);
  if (result.length === 0 || result[0].values.length === 0) return null;

  const row = result[0].values[0];
  return {
    id: row[0],
    user_id: row[1],
    title: row[2],
    description: row[3],
    status: row[4],
    created_at: row[5]
  };
}

function deleteTask(id) {
  const result = db.exec(`DELETE FROM tasks WHERE id = ${id}`);
  return result;
}

// Save database to file (placeholder for now)
function saveDb() {
  // In-memory database for now
}

module.exports = {
  initDb,
  getDb,
  saveDb,
  insertUser,
  getUserByEmail,
  insertTask,
  getTasksByUserId,
  updateTask,
  deleteTask
};

/**
 * Converts basic Markdown to HTML using regex patterns
 * @param {string} text - The markdown text to convert
 * @returns {string} - The converted HTML
 */
function convertMarkdown(text) {
  if (!text) return '';

  let html = text;

  // Convert code blocks first (```...```)
  html = html.replace(/```([\s\S]*?)```/g, '<pre><code>$1</code></pre>');

  // Convert headers (### H3, ## H2, # H1)
  html = html.replace(/^### (.+)$/gm, '<h3>$1</h3>');
  html = html.replace(/^## (.+)$/gm, '<h2>$1</h2>');
  html = html.replace(/^# (.+)$/gm, '<h1>$1</h1>');

  // Convert bold (**text**)
  html = html.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');

  // Convert italic (*text*)
  html = html.replace(/\*([^*]+)\*/g, '<em>$1</em>');

  // Convert unordered lists (lines starting with -)
  // Split into lines and process
  const lines = html.split('\n');
  const processedLines = [];
  let inList = false;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();

    if (line.startsWith('- ')) {
      if (!inList) {
        processedLines.push('<ul>');
        inList = true;
      }
      processedLines.push(`<li>${line.substring(2)}</li>`);
    } else {
      if (inList) {
        processedLines.push('</ul>');
        inList = false;
      }
      processedLines.push(line);
    }
  }

  if (inList) {
    processedLines.push('</ul>');
  }

  html = processedLines.join('\n');

  // Convert paragraphs (blank-line-separated text)
  // Split by double newlines to get paragraphs
  const paragraphs = html.split('\n\n');
  const processedParagraphs = [];

  for (const paragraph of paragraphs) {
    const trimmed = paragraph.trim();
    if (trimmed === '') continue;

    // Don't wrap headers, lists, or code blocks in <p> tags
    if (trimmed.startsWith('<h') || 
        trimmed.startsWith('<ul>') || 
        trimmed.startsWith('<pre>') ||
        trimmed.includes('<li>')) {
      processedParagraphs.push(trimmed);
    } else {
      // Only wrap in <p> if it's not empty and not already an HTML element
      if (trimmed && !trimmed.startsWith('<')) {
        processedParagraphs.push(`<p>${trimmed}</p>`);
      } else {
        processedParagraphs.push(trimmed);
      }
    }
  }

  return processedParagraphs.join('\n\n');
}

module.exports = {
  convertMarkdown
};

const express = require('express');
const { getDb, insertTask, getTasksByUserId, updateTask, deleteTask } = require('../db');
const { validateTask } = require('../middleware/validate');
const { authenticateToken } = require('../middleware/auth');

const router = express.Router();

