const express = require('express');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const { getDb, insertUser, getUserByEmail } = require('../db');
const { validateAuth } = require('../middleware/validate');

const router = express.Router();

// POST /api/auth/register
router.post('/register', validateAuth, async (req, res) => {
  try {
    const { email, password } = req.body;

    // Check if user already exists
    const existingUser = getUserByEmail(email);
    if (existingUser) {
      return res.status(409).json({ error: 'User already exists' });
    }

    // Hash password
    const saltRounds = 10;
    const passwordHash = await bcrypt.hash(password, saltRounds);

    // Insert user
    const user = insertUser(email, passwordHash);

    if (!user) {
      return res.status(500).json({ error: 'Failed to create user' });
    }

    // Return user without password hash
    res.status(201).json({
      id: user.id,
      email: user.email
    });

  } catch (error) {
    console.error('Registration error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// POST /api/auth/login
router.post('/login', validateAuth, async (req, res) => {
  try {
    const { email, password } = req.body;

    // Find user
    const user = getUserByEmail(email);
    if (!user) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Check password
    const isPasswordValid = await bcrypt.compare(password, user.password_hash);
    if (!isPasswordValid) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Generate JWT token
    const jwtSecret = process.env.JWT_SECRET || 'dev-secret';
    const token = jwt.sign(
      { userId: user.id, email: user.email },
      jwtSecret,
      { expiresIn: '24h' }
    );

    res.json({ token });

  } catch (error) {
    console.error('Login error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

module.exports = router;

const jwt = require('jsonwebtoken');

// JWT authentication middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer <token>

  if (!token) {
    return res.status(401).json({ error: 'unauthorized' });
  }

  const jwtSecret = process.env.JWT_SECRET || 'dev-secret';

  jwt.verify(token, jwtSecret, (err, decoded) => {
    if (err) {
      return res.status(401).json({ error: 'unauthorized' });
    }

    // Set userId from the token payload
    req.userId = decoded.userId;
    next();
  });
}

module.exports = {
  authenticateToken
};

// Validation middleware for task requests
function validateTask(req, res, next) {
  const { title, status, description } = req.body;

  // Title validation - required for POST, optional for PUT
  if (req.method === 'POST' && (!title || typeof title !== 'string' || title.trim() === '')) {
    return res.status(400).json({ error: 'Title is required and must be a non-empty string' });
  }

  // Title validation for PUT - if provided, must be non-empty string
  if (req.method === 'PUT' && title !== undefined && (typeof title !== 'string' || title.trim() === '')) {
    return res.status(400).json({ error: 'Title must be a non-empty string' });
  }

  // Status validation - if provided, must be one of the allowed values
  if (status !== undefined && !['pending', 'in_progress', 'done'].includes(status)) {
    return res.status(400).json({ error: 'Status must be one of: pending, in_progress, done' });
  }

  // Description is optional - no validation needed

  next();
}

// Validation middleware for auth requests
function validateAuth(req, res, next) {
  const { email, password } = req.body;

  // Email validation
  if (!email || typeof email !== 'string') {
    return res.status(400).json({ error: 'Email is required and must be a string' });
  }

  // Basic email format validation (must contain @ and a dot)
  if (!email.includes('@') || !email.includes('.')) {
    return res.status(400).json({ error: 'Email must be a valid email address' });
  }

  // Password validation
  if (!password || typeof password !== 'string') {
    return res.status(400).json({ error: 'Password is required and must be a string' });
  }

  if (password.length < 8) {
    return res.status(400).json({ error: 'Password must be at least 8 characters long' });
  }

  next();
}

module.exports = {
  validateTask,
  validateAuth
};

