const { getDb } = require('./db');
const { convertMarkdown } = require('./utils/markdown');

// Helper function to get tasks from the last 7 days for a user
function getTasksLastWeek(userId) {
  const db = getDb();
  const result = db.exec(`
    SELECT * FROM tasks 
    WHERE user_id = ${userId} 
      AND datetime(created_at) >= datetime('now', '-7 days')
    ORDER BY status, created_at DESC
  `);

  if (result.length === 0) return [];

  return result[0].values.map(row => ({
    id: row[0],
    user_id: row[1],
    title: row[2],
    description: row[3],
    status: row[4],
    created_at: row[5]
  }));
}

// Helper function to insert report
function insertReport(userId, title, contentHtml) {
  const db = getDb();
  db.exec(`
    INSERT INTO reports (user_id, title, content_html, generated_at) 
    VALUES (${userId}, '${title.replace(/'/g, "''")}', '${contentHtml.replace(/'/g, "''")}', datetime('now'))
  `);

  // Get the inserted report
  const result = db.exec(`
    SELECT * FROM reports 
    WHERE user_id = ${userId} AND title = '${title.replace(/'/g, "''")}' 
    ORDER BY id DESC LIMIT 1
  `);

  if (result.length === 0 || result[0].values.length === 0) return null;

  const row = result[0].values[0];
  return {
    id: row[0],
    user_id: row[1],
    title: row[2],
    content_html: row[3],
    generated_at: row[4]
  };
}

// Helper function to get all reports for a user
function getReportsByUserId(userId) {
  const db = getDb();
  const result = db.exec(`SELECT * FROM reports WHERE user_id = ${userId} ORDER BY generated_at DESC`);
  if (result.length === 0) return [];

  return result[0].values.map(row => ({
    id: row[0],
    user_id: row[1],
    title: row[2],
    content_html: row[3],
    generated_at: row[4]
  }));
}

// Generate weekly report for a user
function generateWeeklyReport(userId) {
  try {
    // Get tasks from the last 7 days
    const tasks = getTasksLastWeek(userId);

    // Group tasks by status
    const groupedTasks = {
      pending: tasks.filter(task => task.status === 'pending'),
      in_progress: tasks.filter(task => task.status === 'in_progress'),
      done: tasks.filter(task => task.status === 'done')
    };

    // Generate current date for title
    const now = new Date();
    const dateStr = now.toISOString().split('T')[0]; // YYYY-MM-DD format
    const reportTitle = `Weekly Report - ${dateStr}`;

    // Build Markdown content
    let markdownContent = `# ${reportTitle}\n\n`;
    markdownContent += `Generated on ${now.toDateString()}\n\n`;
    markdownContent += `Total tasks created in the last 7 days: ${tasks.length}\n\n`;

    // Add sections for each status
    const statusLabels = {
      pending: 'Pending Tasks',
      in_progress: 'In Progress Tasks', 
      done: 'Completed Tasks'
    };

    Object.keys(groupedTasks).forEach(status => {
      const statusTasks = groupedTasks[status];
      markdownContent += `## ${statusLabels[status]}\n\n`;

      if (statusTasks.length === 0) {
        markdownContent += `No ${status.replace('_', ' ')} tasks in the last week.\n\n`;
      } else {
        statusTasks.forEach(task => {
          markdownContent += `- ${task.title}\n`;
        });
        markdownContent += '\n';
      }
    });

    // Convert Markdown to HTML
    const contentHtml = convertMarkdown(markdownContent);

    // Insert report into database
    const report = insertReport(userId, reportTitle, contentHtml);

    if (!report) {
      throw new Error('Failed to save report to database');
    }

    return {
      id: report.id,
      title: report.title,
      content_html: report.content_html,
      generated_at: report.generated_at
    };

  } catch (error) {
    console.error('Error generating weekly report:', error);
    throw error;
  }
}

module.exports = {
  generateWeeklyReport,
  getReportsByUserId
};

const test = require('node:test');
const assert = require('node:assert');
const { spawn } = require('node:child_process');
const { initDb } = require('../db');

// Helper function to make HTTP requests
async function makeRequest(method, path, data = null, token = null) {
  return new Promise((resolve, reject) => {
    const options = {
      hostname: 'localhost',
      port: 3001, // Use different port for tests
      path,
      method,
      headers: {
        'Content-Type': 'application/json',
        ...(token && { 'Authorization': `Bearer ${token}` })
      }
    };

    const http = require('http');
    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });
      res.on('end', () => {
        try {
          const jsonData = data ? JSON.parse(data) : {};
          resolve({ status: res.statusCode, data: jsonData, headers: res.headers });
        } catch (e) {
          resolve({ status: res.statusCode, data, headers: res.headers });
        }
      });
    });

    req.on('error', reject);

    if (data) {
      req.write(JSON.stringify(data));
    }
    req.end();
  });
}

