    const response = await makeRequest('GET', '/api/tasks', null, testToken);

    assert.strictEqual(response.status, 200);
    assert.ok(Array.isArray(response.data));
    // Should be empty initially
    assert.strictEqual(response.data.length, 0);
  });

  await t.test('GET /api/tasks returns 401 without auth token', async () => {
    const response = await makeRequest('GET', '/api/tasks');

    assert.strictEqual(response.status, 401);
    assert.strictEqual(response.data.error, 'unauthorized');
  });

  let createdTaskId;

  await t.test('POST /api/tasks creates a task and returns 201', async () => {
    const response = await makeRequest('POST', '/api/tasks', {
      title: 'Test Task',
      description: 'This is a test task'
    }, testToken);

    assert.strictEqual(response.status, 201);
    assert.ok(response.data.id);
    assert.strictEqual(response.data.title, 'Test Task');
    assert.strictEqual(response.data.description, 'This is a test task');
    assert.strictEqual(response.data.status, 'pending');
    assert.strictEqual(response.data.user_id, testUserId);
    createdTaskId = response.data.id;
  });

  await t.test('POST /api/tasks without title returns 400 (validation)', async () => {
    const response = await makeRequest('POST', '/api/tasks', {
