const test = require('node:test');
const assert = require('node:assert');
const { convertMarkdown } = require('./markdown');

test('Markdown converter tests', async (t) => {
  await t.test('converts headers', () => {
    assert.strictEqual(convertMarkdown('# Header 1'), '<h1>Header 1</h1>');
    assert.strictEqual(convertMarkdown('## Header 2'), '<h2>Header 2</h2>');
    assert.strictEqual(convertMarkdown('### Header 3'), '<h3>Header 3</h3>');
  });

  await t.test('converts bold text', () => {
    assert.strictEqual(convertMarkdown('**bold text**'), '<strong>bold text</strong>');
    assert.strictEqual(convertMarkdown('This is **bold** text'), '<p>This is <strong>bold</strong> text</p>');
  });

  await t.test('converts italic text', () => {
    assert.strictEqual(convertMarkdown('*italic text*'), '<em>italic text</em>');
    assert.strictEqual(convertMarkdown('This is *italic* text'), '<p>This is <em>italic</em> text</p>');
  });

  await t.test('converts unordered lists', () => {
    const input = '- Item 1\n- Item 2\n- Item 3';
    const expected = '<ul>\n<li>Item 1</li>\n<li>Item 2</li>\n<li>Item 3</li>\n</ul>';
    assert.strictEqual(convertMarkdown(input), expected);
  });

  await t.test('converts code blocks', () => {
    const input = '```\ncode here\n```';
    const expected = '<pre><code>\ncode here\n</code></pre>';
    assert.strictEqual(convertMarkdown(input), expected);
  });

  await t.test('converts paragraphs', () => {
    const input = 'Paragraph 1\n\nParagraph 2';
    const expected = '<p>Paragraph 1</p>\n\n<p>Paragraph 2</p>';
    assert.strictEqual(convertMarkdown(input), expected);
  });

  await t.test('handles complex markdown', () => {
    const input = '# Title\n\nThis is **bold** and *italic*.\n\n- List item 1\n- List item 2\n\n```\ncode block\n```';
    const result = convertMarkdown(input);

    // Check that it contains all expected elements
    assert.ok(result.includes('<h1>Title</h1>'));
    assert.ok(result.includes('<strong>bold</strong>'));
    assert.ok(result.includes('<em>italic</em>'));
    assert.ok(result.includes('<ul>'));
    assert.ok(result.includes('<li>List item 1</li>'));
    assert.ok(result.includes('<pre><code>'));
  });

  await t.test('handles empty input', () => {
    assert.strictEqual(convertMarkdown(''), '');
    assert.strictEqual(convertMarkdown(null), '');
    assert.strictEqual(convertMarkdown(undefined), '');
  });
});

const { initDb, getDb, saveDb } = require('./db');

async function runTests() {
  try {
    console.log('Starting database tests...');

    // Initialize database
    await initDb();
    const db = getDb();

    console.log('✅ Database initialized successfully');

    // Test inserting a user
    const insertUser = db.prepare(`
      INSERT INTO users (email, password_hash) 
      VALUES (?, ?)
    `);

    const userResult = insertUser.run('test@example.com', 'hashed_password_123');
    const userId = userResult.lastInsertRowid;
    console.log('✅ User inserted with ID:', userId);

    // Test inserting a task
    const insertTask = db.prepare(`
      INSERT INTO tasks (user_id, title, description, status) 
      VALUES (?, ?, ?, ?)
    `);

    const taskResult = insertTask.run(userId, 'Test Task', 'This is a test task', 'pending');
    const taskId = taskResult.lastInsertRowid;
    console.log('✅ Task inserted with ID:', taskId);

    // Test inserting a report
    const insertReport = db.prepare(`
      INSERT INTO reports (user_id, title, content_html) 
      VALUES (?, ?, ?)
    `);

    const reportResult = insertReport.run(userId, 'Test Report', '<h1>Test Report Content</h1>');
    const reportId = reportResult.lastInsertRowid;
    console.log('✅ Report inserted with ID:', reportId);

    // Test querying data
    const users = db.exec('SELECT * FROM users');
    console.log('✅ Users table query successful. Records:', users[0]?.values?.length || 0);

    const tasks = db.exec('SELECT * FROM tasks');
    console.log('✅ Tasks table query successful. Records:', tasks[0]?.values?.length || 0);

    const reports = db.exec('SELECT * FROM reports');
    console.log('✅ Reports table query successful. Records:', reports[0]?.values?.length || 0);

    // Test constraint on task status
    try {
      const invalidTask = db.prepare(`
        INSERT INTO tasks (user_id, title, status) 
        VALUES (?, ?, ?)
      `);
      invalidTask.run(userId, 'Invalid Task', 'invalid_status');
      console.log('❌ Should have failed with invalid status');
    } catch (error) {
      console.log('✅ Status constraint working - invalid status rejected');
    }

    // Test unique email constraint
    try {
      const duplicateUser = db.prepare(`
        INSERT INTO users (email, password_hash) 
        VALUES (?, ?)
      `);
      duplicateUser.run('test@example.com', 'another_password');
      console.log('❌ Should have failed with duplicate email');
    } catch (error) {
      console.log('✅ Email uniqueness constraint working - duplicate email rejected');
    }

    // Save database
    saveDb();
    console.log('✅ Database saved successfully');

    console.log('\n🎉 All database tests passed!');

  } catch (error) {
    console.error('❌ Test failed:', error);
    process.exit(1);
  }
}

